-- Morumbi: R$ 65.992 (70% das fichas de 145.000 × 65%)
UPDATE faturamentos SET cat5 = '65992.00' 
WHERE empresaSlug = 'morumbi' AND data = '2026-03-01' AND tenantId = (SELECT tenantId FROM cashbarberConfig WHERE empresaSlug = 'morumbi' LIMIT 1);

